const FAQ_DATA:{section:string;q:string;a:string}[]=[
  {section:"Buying",q:"How do I buy a property through Flatsincity?",a:"Search, open View Detail, and use Enquire. Our team connects you through Flatsincity. Seller numbers are never shown directly."},
  {section:"Buying",q:"What is the Flatsincity Recommended Price in Buyer Detail?",a:"It is an opinion to help the buyer decide, based on available information and local factors. It is not to damage the seller and is not a guarantee. It appears only inside Buyer Property Detail — the seller view hides it."},
  {section:"Buying",q:"What is the expected timeframe for buying?",a:"Expected Timeframe — Sale: 90 days. This is an opinion based on market, not a guarantee."},
  {section:"Selling",q:"How do I sell my property?",a:"Choose Category first, then complete only that category form, add Address, GPS pin and Price, and submit for approval."},
  {section:"Selling",q:"Can I change my price after posting?",a:"Yes — maximum once in 7 days. Price history is shown on the listing."},
  {section:"Selling",q:"How long is a listing valid?",a:"A listing is valid for 6 months, then it needs Renew."},
  {section:"Renting",q:"What is the expected timeframe for rent?",a:"Expected Timeframe — Rent: 30 days. This is an opinion based on market, not a guarantee."},
  {section:"Renting",q:"What is Owner Agreed Rent?",a:"In Rent / Lease / Manage, the owner agreed amount is the management figure. It never appears in a Sell form."},
  {section:"Renting",q:"When is rent due?",a:"Rent is due on or before the 5th of the month, as per the management terms."},
  {section:"PG",q:"How does PG advance work?",a:"PG Advance is 3 Months Rent (PG Standard). It is auto-calculated from the rent per bed for the selected sharing."},
  {section:"Who Can Post",q:"Who can post a property?",a:"Owner, Builder, Broker, Banker, Fl.Exe (Flatsincity Field Executive) and Field Partner can post. Owner, Builder, Broker and Banker self-register with Mobile + OTP. Fl.Exe, Sub-Admin and Field Partner logins are created by the level above them."},
  {section:"Who Can Post",q:"What is the login hierarchy?",a:"Admin (Main Admin) creates Sub-Admin only. Sub-Admin creates Flatsincity Manager only and can Verify / Approve. Manager creates Flatsincity Executive (Fl.Exe) only. Fl.Exe creates Field Partner login. Field Partner comes under that Fl.Exe's team."},
  {section:"Who Can Post",q:"Can a Field Partner login or register by self?",a:"Field Partner cannot self-register. You must be selected by your Flatsincity Executive. After he creates your login, you can login here with your credential."},
  {section:"Who Can Post",q:"How does Field Partner / Fl.Exe posting approval work?",a:"Field Partner or Fl.Exe posts the property with the Owner / Broker / Builder name, mobile and type. It stays Pending Approval (Sub-Admin). Sub-Admin talks to the concerned person on that number and only approves if he confirms. After approval the concerned person gets a WhatsApp message with the Property ID and an AI Poster, and can login with Mobile + OTP and make changes."},
  {section:"Who Can Post",q:"Is a Field Partner an employee of Flatsincity?",a:"No. Field Partner (Gig worker / Broker) is not an employee. Fl.Exe is an employee of Flatsincity. Field Partner is paid per property details uploaded — pay rules are Admin-only and never shown in public."},
  {section:"PG",q:"What PG details do I need to post?",a:"PG Name, Sharing, Rent per Bed, Food and Food Timings, Facilities, Rules, Vacant Beds and Curfew / Entry Timings."},
  {section:"Posting",q:"One Property = One Listing — what does it mean?",a:"The same address with the same mobile cannot be posted twice. A duplicate is blocked."},
  {section:"Posting",q:"Is GPS compulsory?",a:"Yes. Mark the GPS of the property, not your current location. Click or drag the pin, or enter coordinates. If marking is wrong, the poster can correct it."},
  {section:"Posting",q:"Can I edit my listing?",a:"Yes — you can edit everything except Mobile and Email. Mobile can never be edited."},
  {section:"Loans",q:"Which loan types are available?",a:"Property Purchase, Loan Against Property / Mortgage, Renovation, Balance Transfer, Top-Up and Personal Loan."},
  {section:"Loans",q:"How is EMI calculated?",a:"EMI = P × r × (1+r)^n / ((1+r)^n − 1), where r is monthly interest and n is total months. Use Calculate EMI in the Loans section."},
  {section:"Loans",q:"Which bank types can I choose?",a:"National, Multinational, Private, NBFC and Co-operative. Choose the bank type, then the bank name."},
  {section:"Manage",q:"What is Manage My Property?",a:"For owners — tell Flatsincity what you need: Manage, Renovate, Find Tenant, or Flatsincity to Sell. A Flatsincity Executive will connect you based on your inquiry."},
  {section:"Manage",q:"What is the expected timeframe for lease?",a:"Expected Timeframe — Lease: 45 days. This is an opinion based on market, not a guarantee."},
  {section:"Field Executive",q:"How do I join as a Field Executive?",a:"Fill the Join as Field Executive form. The office will explain the next steps."},
  {section:"Field Executive",q:"Do I need to pay to join?",a:"No payment is asked in this form. Fill the form and the office will explain."},
  {section:"Safety / OTP",q:"Is there OTP on the road?",a:"No OTP on road. Owner OTP is on the owner’s own phone only."},
  {section:"Safety / OTP",q:"Can I change my mobile later?",a:"No. Mobile can never be edited. It is locked to the account."},
  {section:"Safety / OTP",q:"Can I change Name / Mail?",a:"Yes — Name / Mail can be edited once only. After that it cannot be changed."},
  {section:"Safety / OTP",q:"Will my number be shown to buyers?",a:"No. Listings show Posted via Flatsincity where applicable, and enquiries are routed through Flatsincity."},
];
const BANK_TYPES:Record<string,string[]>={"National":["State Bank of India","Punjab National Bank","Bank of Baroda","Canara Bank","Union Bank of India"],"Multinational":["HSBC","Citibank","Standard Chartered","Deutsche Bank"],"Private":["HDFC Bank","ICICI Bank","Axis Bank","Kotak Mahindra Bank"],"NBFC":["HDFC Housing Finance","LIC Housing Finance","Bajaj Finserv","Tata Capital"],"Co-operative":["Karnataka State Co-operative Bank","Saraswat Co-operative Bank","Local Co-operative Bank"]};
function CurrencyMeter({label,value,onChange,min,max,step,presets,overCapHint}:{label:string;value:number;onChange:(v:number)=>void;min:number;max:number;step:number;presets:{label:string;value:number}[];overCapHint?:string}){
  const effMax=Math.max(max, value||0);
  const handleText=(raw:string)=>{ const digits=raw.replace(/[^0-9]/g,""); onChange(digits?Number(digits):0); };
  const overCap = (value||0) > max;
  const isLargeScale = max>100000000;
  const fineStep = isLargeScale ? 100000 : 1000;
  const fineMax = Math.min(10000000, effMax);
  const sliderStep = (value||0) < 10000000 ? fineStep : Math.max(step, isLargeScale ? 1000000 : 10000);
  const showFine = (value||0) <= 10000000;
  const adjustFine = (delta:number)=>{ onChange(Math.max(0, Math.min(effMax, (value||0)+delta))); };
  return <div className="border rounded-xl p-3" style={{background:"var(--soft)"}}>
    <div className="flex justify-between items-baseline gap-2 flex-wrap"><label style={{marginBottom:0}}>{label}</label><span className="font-display text-lg" style={{color:"var(--navy)"}}>{formatShort(value)}</span></div>
    <p className="small" style={{marginTop:-2}}>Slider {formatShort(min)} – {formatShort(max)}. Type any amount above the slider if needed — it is not blocked.</p>
    <input type="range" aria-label={label} min={min} max={effMax} step={sliderStep} value={Math.max(min,Math.min(effMax,value||0))} onChange={e=>onChange(Number(e.target.value))} style={{width:"100%",accentColor:"var(--gold)",cursor:"pointer"}} />
    {showFine && <div className="mt-2">
      <label style={{marginBottom:4}}>Fine control — 0 to ₹1 Cr ({isLargeScale ? "₹1 Lakh steps" : "₹1,000 steps"})</label>
      <input type="range" aria-label={`${label} — fine control 0 to 1 Cr`} min={0} max={fineMax} step={fineStep} value={Math.max(0,Math.min(fineMax,value||0))} onChange={e=>onChange(Number(e.target.value))} style={{width:"100%",accentColor:"var(--gold)",cursor:"pointer"}} />
      <div className="flex gap-2 mt-1"><button type="button" className="chip" onClick={()=>adjustFine(-fineStep)}>− {formatShort(fineStep)}</button><button type="button" className="chip" onClick={()=>adjustFine(fineStep)}>+ {formatShort(fineStep)}</button><span className="small self-center">Use this for low values such as {isLargeScale ? "₹5 Lakhs, ₹10 Lakhs or ₹25 Lakhs" : "₹5,000, ₹10,000 or ₹25,000"}.</span></div>
    </div>}
    <div className="flex items-center gap-2 mt-1"><span className="font-bold">₹</span><input aria-label={`${label} — type amount`} value={value?String(value):""} onChange={e=>handleText(e.target.value)} inputMode="numeric" placeholder="Type amount" /></div>
    <div className="flex flex-wrap gap-2 mt-2">{presets.map(p=><button key={p.label} type="button" className={`chip ${value===p.value?"active":""}`} onClick={()=>onChange(p.value)}>{p.label}</button>)}</div>
    {overCap && overCapHint && <p className="text-xs mt-2 font-semibold" style={{color:"var(--navy)"}} role="status">{overCapHint}</p>}
    <p className="small mt-2">Drag the slider or type the amount — both stay in sync.</p>
  </div>;
}
function parseCoords(s?:string){ if(!s) return null; const m=s.match(/(-?\d{1,3}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/); if(!m) return null; const lat=Number(m[1]), lng=Number(m[2]); if(Math.abs(lat)>90||Math.abs(lng)>180) return null; return {lat,lng}; }
function hasPincode(s:string){ return /\b\d{6}\b/.test(s); }
function addressOk(a1:string, a2:string){ return a1.trim().length>0 && a2.trim().length>0 && hasPincode(a2); }
function distanceKm(a:{lat:number,lng:number}, b:{lat:number,lng:number}){ const R=6371; const dLat=(b.lat-a.lat)*Math.PI/180; const dLng=(b.lng-a.lng)*Math.PI/180; const s=Math.sin(dLat/2)**2+Math.cos(a.lat*Math.PI/180)*Math.cos(b.lat*Math.PI/180)*Math.sin(dLng/2)**2; return 2*R*Math.asin(Math.sqrt(s)); }
function listingCoords(l:any){ return parseCoords(l.gps) || (typeof l.lat==="number" && typeof l.lng==="number" ? {lat:l.lat,lng:l.lng} : null); }
