    try{ await api("records.create",{collection:"fl_exe_daily", value, idempotency_key:`flexe-${exe}-${flExeForm.date}-${Date.now()}`}); setNotice("Admin: Fl.Exe daily entry saved as Pending."); setFlExeForm({...flExeForm, added:"", override:false, overrideReason:""}); setFlExeName(exe); await load(); }
